using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class IslandAudioChecks {
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyDestroyedListener(){
  Require(EditorApplication.isPlaying&&IslandAudio.Current!=null,"Enter Play mode");var audio=IslandAudio.Current;
  foreach(var name in new[]{"head","rig"}){var field=typeof(IslandAudio).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic);var original=field.GetValue(audio);var temporary=new GameObject("Temporary destroyed audio reference");field.SetValue(audio,temporary.transform);UnityEngine.Object.DestroyImmediate(temporary);try{Require(!audio.Emit(IslandSound.Notice,Vector3.zero,991),"Audio accepted destroyed "+name);}finally{field.SetValue(audio,original);}}
  Debug.Log("BWVR_AUDIO_LIFECYCLE_PASS: destroyed listener/rig reject cues without accessing retired transforms");
 }
 [MenuItem("BWVR/Verify island audio (Play mode)")]
 public static void Verify(){
  Require(EditorApplication.isPlaying,"Enter Play mode");var audio=IslandAudio.Current;Require(audio!=null,"No soundscape");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var world=slice.GetComponentInChildren<VillageResources>();var state=world.Season;bool paused=state.paused;float master=audio.Master,ambience=audio.Ambience,effects=audio.Effects;
  string[] keys={"BWVR.Audio.master","BWVR.Audio.ambience","BWVR.Audio.effects"};var had=keys.Select(PlayerPrefs.HasKey).ToArray();var values=keys.Select(k=>PlayerPrefs.GetFloat(k)).ToArray();float rain=state.Weather.rain,wind=state.Weather.wind,miracleRain=state.Hybrid.rainRemaining;var rig=(Transform)typeof(QuestSlice).GetField("rig",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(slice);var scale=rig.localScale;
  try{
   Require(UnityEngine.Object.FindObjectsByType<AudioListener>().Count(l=>l.enabled&&l.gameObject.activeInHierarchy)==1,"Expected one active listener");var sources=audio.GetComponentsInChildren<AudioSource>();Require(sources.Length==12&&sources.Count(s=>s.loop)==3,"Emitter budget changed");var clips=Resources.LoadAll<AudioClip>("IslandAudio");Require(clips.Length==19&&clips.All(c=>c.channels==1&&c.frequency==22050&&c.loadState==AudioDataLoadState.Loaded),"Clips missing, stereo or not loaded");
   long bytes=clips.Sum(c=>(long)c.samples*c.channels*4);Require(bytes<5*1024*1024,"PCM exceeds 5 MB budget");foreach(var clip in clips){var data=new float[clip.samples];Require(clip.GetData(data,0)&&data.Any(x=>Mathf.Abs(x)>.02f)&&data.All(x=>!float.IsNaN(x)&&Mathf.Abs(x)<.9f),"Silent/clipped/nonfinite clip: "+clip.name);}
   state.paused=false;state.Weather.wind=1;state.Weather.rain=0;state.Hybrid.rainRemaining=0;audio.Suspend(false);audio.SetMix(1,1,1,false);for(int i=0;i<30;i++)audio.Advance(.1f,false);
   var at=Camera.main.transform.position+Camera.main.transform.forward*audio.NearDistance;int played=audio.Played;Require(audio.Emit(IslandSound.Grasp,at,100)&&!audio.Emit(IslandSound.Grasp,at,100)&&audio.Played==played+1,"Held/repeated cue stacked");
   audio.SetFrozen(true);Require(audio.ActiveVoices==0&&!audio.Emit(IslandSound.Miracle,at,200),"Pause retained/replayed one-shots");var loopPositions=sources.Where(s=>s.loop).Select(s=>s.timeSamples).ToArray();audio.Advance(10,true);Require(loopPositions.SequenceEqual(sources.Where(s=>s.loop).Select(s=>s.timeSamples)),"Paused loop advanced");audio.SetFrozen(false);Require(audio.ActiveVoices==0,"Resume replayed stopped effects");audio.Suspend(true);Require(!audio.Emit(IslandSound.Grasp,at,300),"Suspend played effect");audio.Suspend(false);
   audio.SetMix(0,1,1,false);Require(sources.All(s=>s.volume==0)&&!audio.Emit(IslandSound.Miracle,at,400),"Master mute leaked");audio.SetMix(1,1,0,false);Require(!audio.Emit(IslandSound.Step,at,500),"Effects mute leaked");audio.SetMix(1,0,1,false);Require(sources.Where(s=>s.loop).All(s=>s.volume==0),"Ambience mute leaked");audio.SetMix(float.NaN,1,1,false);Require(audio.Master==1&&audio.Ambience==0,"Invalid mix corrupted levels");audio.SetMix(.25f,.5f,.75f);Require(PlayerPrefs.GetFloat(keys[0])==.25f&&PlayerPrefs.GetFloat(keys[1])==.5f&&PlayerPrefs.GetFloat(keys[2])==.75f,"Mix not stored independently");audio.SetMix(1,1,1,false);
   for(int i=0;i<30;i++)audio.Advance(.1f,false);int start=audio.Played;for(int i=0;i<100;i++){audio.Emit((IslandSound)(i%15),at,i+1000);Require(audio.ActiveVoices<=IslandAudio.VoiceLimit,"Voice cap exceeded");}Require(audio.Played>start&&audio.Dropped>0,"Flood fixture did not play/drop voices");Require(!audio.Emit(IslandSound.Ball,at+Vector3.one*audio.FarDistance*5,99),"Distant crowd accepted");
   var walker=world.Gatherers[0].GetComponent<HumanoidMotion>();var actor=walker.GetComponent<CarryItem>();var oldPosition=walker.transform.position;bool held=actor.held,motionPaused=walker.paused;walker.paused=false;
   try{for(int i=0;i<20;i++)audio.Advance(.1f,false);int silent=audio.Played;actor.held=true;walker.transform.position+=Vector3.right*walker.transform.lossyScale.y;audio.Advance(.1f,false);Require(audio.Played==silent,"Carried walker made footsteps");actor.held=false;walker.transform.position=oldPosition+Vector3.up*world.Navigation.Scale*30;audio.Advance(.1f,false);Require(audio.Played==silent,"Hovering walker made footsteps");walker.transform.position=oldPosition;audio.Advance(.1f,false);for(int i=0;i<20;i++)audio.Advance(.1f,false);silent=audio.Played;walker.transform.position=world.Navigation.ProjectFoot(oldPosition+Vector3.right*walker.transform.lossyScale.y*.55f,world.Navigation.villager);audio.Advance(.1f,false);Require(audio.Played>silent,"Grounded moving walker made no footstep");}
   finally{actor.held=held;walker.paused=motionPaused;walker.transform.position=oldPosition;audio.Advance(.1f,false);}
   state.Weather.rain=1;state.Weather.wind=1;float before=audio.RainLevel;audio.Advance(.1f,false);Require(audio.RainLevel>before&&audio.RainLevel-before<.02f,"Rain transition not a bounded fade");
   rig.localScale=Vector3.one*.2f;float near=audio.NearDistance,far=audio.FarDistance;rig.localScale=Vector3.one*2;Require(audio.NearDistance>=near&&audio.FarDistance>=far&&audio.NearDistance<audio.FarDistance,"Zoom distances invalid");
   var ui=(GameObject)typeof(QuestSlice).GetField("audioSettings",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(slice);Require(ui!=null&&!ui.activeSelf,"Audio settings not hidden");var show=typeof(QuestSlice).GetMethod("ShowAudioSettings",BindingFlags.Instance|BindingFlags.NonPublic);show.Invoke(slice,new object[]{true});Require(ui.activeSelf&&ui.GetComponentsInChildren<SpatialTarget>().Length==5,"Audio settings inaccessible");show.Invoke(slice,new object[]{false});
   Debug.Log("BWVR_AUDIO_PASS: one listener, 19 audible finite mono clips, <5MB PCM, 3 loops + 8 bounded voices, contact/repetition limits, pause/suspend/resume no stale shots, independent persistent mute/mix, distance rejection, weather fade, zoom falloff, optional wrist settings. Headset listening/performance pending.");
  }finally{state.paused=paused;state.Weather.rain=rain;state.Weather.wind=wind;state.Hybrid.rainRemaining=miracleRain;rig.localScale=scale;audio.SetMix(master,ambience,effects,false);for(int i=0;i<keys.Length;i++){if(had[i])PlayerPrefs.SetFloat(keys[i],values[i]);else PlayerPrefs.DeleteKey(keys[i]);}PlayerPrefs.Save();audio.SetFrozen(paused);}
 }
}
}
